# owner: platform
import unittest

from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("1001", "Thistle", "Bram", "A")


def make_mark(day, status, ident="1001"):
    return Mark(ident, date(2026, 3, day), status)


class NoticeTests(unittest.TestCase):
    def test_names_count_and_ordered_dates(self):
        marks = [make_mark(9, "absent"), make_mark(4, "absent"), make_mark(5, "present")]
        self.assertEqual(
            build_notice(PUPIL, marks),
            "Bram Thistle was absent for 2 days: 2026-03-04, 2026-03-09."
        )

    def test_single_day_is_singular(self):
        text = build_notice(PUPIL, [make_mark(4, "absent")])
        self.assertIn("1 day:", text)

    def test_other_statuses_are_ignored(self):
        marks = [make_mark(4, "late"), make_mark(5, "excused"), make_mark(6, "absent")]
        self.assertIn("2026-03-06.", build_notice(PUPIL, marks))

    def test_foreign_mark_is_rejected(self):
        marks = [make_mark(4, "absent"), make_mark(4, "absent", "2002")]
        with self.assertRaises(ValueError):
            build_notice(PUPIL, marks)

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [make_mark(4, "present")])

    def test_no_marks_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [])
